 static Bitmap decode(byte[] b){Bitmap m=Bitmap.createBitmap(800,480,Bitmap.Config.ARGB_8888);int[] px=new int[384000];for(int i=0;i<px.length;i++)px[i]=b==null||(b[i/8]&(128>>(i%8)))!=0?Color.WHITE:Color.BLACK;m.setPixels(px,0,800,0,0,800,480);return m;}
 static byte[] pack(Bitmap b){byte[] out=new byte[48000];int[] px=new int[384000];b.getPixels(px,0,800,0,0,800,480);for(int i=0;i<px.length;i++)if(Color.red(px[i])*299+Color.green(px[i])*587+Color.blue(px[i])*114>=160000)out[i/8]|=(byte)(128>>(i%8));return out;}
 void clear(float x,float y,float w,float h){p.setColor(Color.WHITE);p.setStyle(Paint.Style.FILL);c.drawRect(x,y,x+w,y+h,p);}
