  for(int i=0;i<Math.min(count,tasks.length());i++){JSONObject t=tasks.getJSONObject(i);float y=160+i*row,left=kind.equals("agenda")?108:48;if(kind.equals("agenda")){String time="待定";try{time=DateTimeFormatter.ofPattern("HH:mm").withZone(ZoneId.of("Asia/Shanghai")).format(Instant.parse(t.getString("due")));}catch(Exception ignored){}text(time,24,y+1,17,76,true);}else check(25,y+5,10);text((t.optBoolean("pinned")?"★ ":"")+t.getString("title"),left,y,19,width-(left-24),DeskModel.overdue(t));text(DeskModel.due(t),left,y+26,12,width-(left-24));}
