 void cards(float x,float width)throws Exception{for(int slot=0;slot<2;slot++){float y=slot==0?120:266;int saved=c.save();c.clipRect(x,y,x+width,y+136);clear(x,y,width,136);String key=cfg.optString(slot==0?"card1":"card2",slot==0?"week":"outdoor");text(ScreenData.label(key),x,y,13,width);rule(x,y+27,width,false);int count=cfg.optInt("_weekCount",0),goal=Math.max(1,cfg.optInt("weeklyGoal",20));switch(key){case "plant":plant(x+width-82,y+37,ScreenData.plantStage(count,goal));text(count+" / "+goal,x,y+45,25,width-86,true);text(cfg.optBoolean("sharedStats")?"共享本周":"本机本周",x,y+83,13,width-86);break;case "week":text("已完成 "+count+" 项",x,y+42,23,width,true);text((cfg.optBoolean("sharedStats")?"共享本周":"本机本周")+" · 目标 "+goal+" 项",x,y+78,13,width);p.setColor(Color.BLACK);p.setStyle(Paint.Style.STROKE);c.drawRect(x,y+109,x+width,y+119,p);p.setStyle(Paint.Style.FILL);c.drawRect(x,y+109,x+width*Math.min(1f,(float)count/goal),y+119,p);break;case "countdown":lines(ScreenData.countdown(cfg,now),x,y+41,20,width,3);break;case "outdoor":lines(ScreenData.outdoor(weather,now),x,y+41,17,width,3);break;case "plugin":lines(CommunityPanel.pluginText(cfg.optJSONObject("plugin")==null?new JSONObject():cfg.optJSONObject("plugin"),now.atZone(ScreenData.ZONE).toLocalDate()),x,y+41,18,width,3);break;case "nextEvent":lines(DeskExtras.eventText(cfg,now),x,y+41,18,width,3);break;case "commute":lines(DeskExtras.commuteText(cfg,now),x,y+41,18,width,3);break;case "habits":lines(DeskExtras.habitText(cfg,now),x,y+41,18,width,3);break;case "inspiration":lines(new String[]{"今天，先做好一件事。","给重要的事留出时间。","慢一点，也在往前。","专注当下的一小步。","让桌面和心情都留白。","完成比完美更有力量。","休息也是今天的安排。"}[now.atZone(ScreenData.ZONE).getDayOfYear()%7],x,y+41,20,width,3);break;case "status":text(cfg.optString("deskStatus","专注中"),x,y+42,27,width,true);text(cfg.optString("statusNote","请稍后联系"),x,y+87,16,width);break;default:lines(cfg.optString("note"),x,y+41,19,width,3);}c.restoreToCount(saved);}}
 void plant(float x,float y,int stage){p.setColor(Color.BLACK);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);Path pot=new Path();pot.moveTo(x+14,y+61);pot.lineTo(x+59,y+61);pot.lineTo(x+53,y+84);pot.lineTo(x+20,y+84);pot.close();c.drawPath(pot,p);if(stage==0){c.drawOval(x+31,y+52,x+41,y+58,p);}else{c.drawLine(x+36,y+61,x+36,y+42-stage*6,p);for(int i=0;i<stage;i++){float at=y+47-i*8;Path leaf=new Path();leaf.moveTo(x+36,at);boolean left=i%2==0;leaf.quadTo(x+(left?9:63),at-23,x+(left?13:60),at-7);leaf.quadTo(x+(left?20:53),at+1,x+36,at);c.drawPath(leaf,p);}}p.setStyle(Paint.Style.FILL);p.setStrokeWidth(1);}
