 void landscape(float x,float y,float width,float height){int saved=c.save();c.clipRect(x,y,x+width,y+height);p.setColor(Color.BLACK);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.3f);c.drawCircle(x+width*.79f,y+height*.24f,14,p);for(int layer=0;layer<3;layer++){Path ridge=new Path();ridge.moveTo(x,y+height);for(int i=0;i<=8;i++){float xx=x+i*width/8,yy=y+height*(.42f+layer*.18f)+(float)Math.sin(i*1.7+layer+now.atZone(ScreenData.ZONE).getMonthValue()*.3)*height*.17f;ridge.lineTo(xx,yy);}ridge.lineTo(x+width,y+height);c.drawPath(ridge,p);}p.setStyle(Paint.Style.FILL);c.restoreToCount(saved);}
